from .core import Agent, Task, Peer
from typing import List

class CoordinatorAgent(Agent):
    """Decomposes tasks and delegates to a dynamic pod of agents."""
    def get_capabilities(self) -> List[str]:
        return super().get_capabilities() + ["coordinate_math_problem"]

    def execute(self, task: Task) -> Task:
        if task.operation == "coordinate_math_problem":
            print(f"[{self.name}] Coordinating task: {task.id}")
            task.status = "in_progress"

            # 1. Find a calculator agent (Morphogenesis)
            calculator_peer = self._find_peer_with_capability("calculate")
            if not calculator_peer:
                task.status = "failed"
                task.result = "No calculator agent available in the mesh."
                return task

            # 2. Find a reporter agent
            reporter_peer = self._find_peer_with_capability("report")
            if not reporter_peer:
                task.status = "failed"
                task.result = "No reporter agent available in the mesh."
                return task

            # 3. Find an artifact agent for persistence
            artifact_peer = self._find_peer_with_capability("store_artifact")
            if not artifact_peer:
                print(f"[{self.name}] Warning: No artifact agent available. Task result will not be persisted.")
                # Not a critical failure for the task itself, but a warning.

            print(f"[{self.name}] Formed pod: [Coordinator, {calculator_peer.name}, {reporter_peer.name}]")

            try:
                # 4. Delegate calculation
                calc_task = Task(id=f"{task.id}-calc", operation=task.params['math_op'], params=task.params['operands'])
                calc_result_task = self.send_request(calculator_peer.uri, "/execute", calc_task.__dict__)

                if calc_result_task['status'] == 'failed':
                    raise ValueError(f"Calculation failed: {calc_result_task['result']}")

                # 5. Delegate reporting
                report_task = Task(id=f"{task.id}-report", operation="format_result", params={"result": calc_result_task['result']})
                report_result_task = self.send_request(reporter_peer.uri, "/execute", report_task.__dict__)

                task.status = "completed"
                task.result = report_result_task['result']
                print(f"[{self.name}] Task {task.id} completed successfully.")

                # 6. Persist the final result using the ArtifactAgent
                if artifact_peer:
                    artifact_id = f"task-result-{task.id}"
                    store_task = Task(id=f"{task.id}-store", operation="store_artifact", 
                                      params={"artifact_id": artifact_id, "data": task.result})
                    store_result = self.send_request(artifact_peer.uri, "/execute", store_task.__dict__)
                    if store_result['status'] == 'completed':
                        print(f"[{self.name}] Task result {artifact_id} persisted by {artifact_peer.name}.")
                    else:
                        print(f"[{self.name}] Failed to persist task result {artifact_id}: {store_result['result']}")


            except Exception as e:
                task.status = "failed"
                task.result = str(e)
                print(f"[{self.name}] Task {task.id} failed: {e}")

            return task
        else:
            task.status = "failed"
            task.result = f"Unknown operation: {task.operation}"
            return task

    def _find_peer_with_capability(self, capability: str) -> Peer | None:
        self.discover_peers() # Refresh peer list
        for peer in self.peer_registry.values():
            if capability in peer.capabilities:
                return peer
        return None


class CalculatorAgent(Agent):
    """A specialist agent that performs calculations."""
    def get_capabilities(self) -> List[str]:
        return super().get_capabilities() + ["calculate"]

    def execute(self, task: Task) -> Task:
        print(f"[{self.name}] Executing calculation: {task.operation}")
        try:
            op = task.operation
            a = task.params['a']
            b = task.params['b']
            if op == "add":
                task.result = a + b
            elif op == "subtract":
                task.result = a - b
            else:
                raise ValueError(f"Unsupported operation: {op}")
            task.status = "completed"
        except Exception as e:
            task.status = "failed"
            task.result = str(e)
        return task


class ReporterAgent(Agent):
    """A specialist agent that formats results for output."""
    def get_capabilities(self) -> List[str]:
        return super().get_capabilities() + ["report"]

    def execute(self, task: Task) -> Task:
        print(f"[{self.name}] Formatting report")
        if task.operation == "format_result":
            task.result = f"Final Report: The result is {task.params['result']}."
            task.status = "completed"
        else:
            task.status = "failed"
            task.result = "Unknown report format"
        return task
